// DBImportsCore lists the Go imports always required by RuntimeDB whenever
// the db module is used, independent of which driver is active.
const DBImportsCore = `
	"database/sql"
	"net/url"
`

// Per-driver import lines. Each is a single blank-import clause that
// registers the driver with database/sql. The generator emits only the
// driver(s) whose scheme it can prove the program connects to; if the DSN
// is not statically known it falls back to all three (DBImports).
const DBImportMysql = `_ "github.com/go-sql-driver/mysql"`
const DBImportPostgres = `_ "github.com/lib/pq"`
const DBImportSqlite = `_ "modernc.org/sqlite"`

// DBImports lists the Go imports required by RuntimeDB.
// Each line is a raw Go import clause, embedded in the import ( ... ) block.
// This is the full union (all three drivers) used as the safe fallback when
// the active driver cannot be determined from the source.
const DBImports = `
	"database/sql"
	"net/url"
	_ "github.com/go-sql-driver/mysql"
	_ "github.com/lib/pq"
	_ "modernc.org/sqlite"
`

// DBKeepAlive lists the Go source lines that must be emitted
// as `var _ = <symbol>` to prevent the linker from dropping their packages.
const DBKeepAlive = `
	sql.Open
`
